        }
    }

    if self.slab.is_empty() {
        if let Some(waker) = self.waker.take() {
            waker.wake();
        }
    }

    Expired {
        key: Key::new(key.index),
        data: data.inner,
        deadline: self.start + Duration::from_millis(data.when),
    }
}

